    static func search(_ query: String) -> [StockEntry] {
        let q = query.lowercased().trimmingCharacters(in: .whitespaces)
        guard !q.isEmpty else { return [] }
        return all.filter {
            $0.ticker.lowercased().contains(q) ||
            $0.companyName.lowercased().contains(q) ||
            $0.sector.lowercased().contains(q)
        }
        .sorted {
            let aTop = $0.ticker.lowercased().hasPrefix(q)
            let bTop = $1.ticker.lowercased().hasPrefix(q)
            if aTop != bTop { return aTop }
            return $0.companyName < $1.companyName
        }
    }
